import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers we are monitoring
MONITORED_PINS = {2, 3, 4}

# Global list so the signal handler can close devices cleanly
_devices: list[DigitalOutputDevice] = []


def _cleanup() -> None:
    """Close every device we opened."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass


def _handle_signal(signum, frame) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    print(f"\nReceived signal {signum}; shutting down.")
    _cleanup()
    sys.exit(0)


def main() -> int:
    # Register signal handlers for clean termination
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Open each pin as a digital output; gpiozero raises DeviceClosed if the
    # pin is already in use or unavailable.
    for pin in MONITORED_PINS:
        try:
            dev = DigitalOutputDevice(pin)
            _devices.append(dev)
            print(f"GPIO {pin} initialized as output.")
        except GPIOZeroError as exc:
            print(f"Error initializing GPIO {pin}: {exc}", file=sys.stderr)
            return 1
        except Exception as exc:
            print(f"Unexpected error opening GPIO {pin}: {exc}", file=sys.stderr)
            return 1

    print("Monitoring GPIO pins 2, 3, 4. Press Ctrl+C to stop.")

    try:
        while True:
            for dev in _devices:
                try:
                    print(f"GPIO {dev.pin.number} state: {'HIGH' if dev.value else 'LOW'}")
                except DeviceClosed:
                    print(f"GPIO {dev.pin.number} closed unexpectedly.", file=sys.stderr)
                    return 1
                except Exception as exc:
                    print(f"Error reading GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                    return 1
            time.sleep(60)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        _cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

