import time
import signal
import sys
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

# Display constants
I2C_PORT = 1
I2C_ADDRESS = 0x3C
UPDATE_INTERVAL_S = 2.0

# Global flag for graceful shutdown
_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def read_sensor_data():
    """Simulates reading sensor data. In production, replace with real sensor reads."""
    return {"temperature": 25.5, "humidity": 60.0}


def validate_data(data):
    """Validates sensor data. Returns True if valid, False otherwise."""
    if not isinstance(data, dict):
        print("Error: Invalid data type. Expected dictionary.")
        return False
    if "temperature" not in data or "humidity" not in data:
        print("Error: Missing required keys in data.")
        return False
    try:
        float(data["temperature"])
        float(data["humidity"])
    except (ValueError, TypeError):
        print("Error: Invalid numeric values in data.")
        return False
    return True


def display_data(device, data):
    """Displays sensor data on the OLED screen."""
    try:
        with canvas(device) as draw:
            draw.text((0, 0), f"Temp: {data['temperature']:.1f} C", fill="white")
            draw.text((0, 12), f"Humidity: {data['humidity']:.1f} %", fill="white")
    except Exception as e:
        print(f"Error displaying data: {e}")


def main():
    """Main function to read sensor data and display it on the OLED screen."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize I2C serial interface for the OLED display
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing I2C interface: {e}")
        sys.exit(1)

    # Initialize the OLED display
    try:
        device = ssd1306(serial)
    except Exception as e:
        print(f"Error initializing OLED display: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                sensor_data = read_sensor_data()
                if validate_data(sensor_data):
                    display_data(device, sensor_data)
                else:
                    print("Skipping invalid data.")
            except Exception as e:
                print(f"Error reading sensor data: {e}")

            # Sleep in small increments to allow prompt signal handling
            slept = 0.0
            while _running and slept < UPDATE_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Clean up resources on all exit paths
        try:
            device.cleanup()
        except Exception:
            pass
        print("Program finished.")


if __name__ == "__main__":
    main()

