    try:
        for pin in PINS:
            dev = PWMOutputDevice(pin=pin, initial_value=0.0)
            devices.append(dev)
    except Exception as exc:
        print(f"Failed to initialize PWM devices: {exc}", file=sys.stderr)
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    dev.value = 0.5
                except Exception as exc:
                    print(f"Error setting PWM value: {exc}", file=sys.stderr)
                    break
            else:
                print("GPIO 1-4 set to 0.5")
            time.sleep(DELAY)
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


