import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_serial_data(serial_port):
    try:
        data = serial_port.readline()
        return data.decode("ascii", errors="replace").strip() if data else None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"I/O error during serial read: {e}", file=sys.stderr)
        return None


def process_data(data):
    if not data:
        return None
    try:
        value = float(data)
    except ValueError:
        print(f"Invalid data received (not a number): '{data}'", file=sys.stderr)
        return None
    if not -100 <= value <= 100:
        print(f"Data out of range (-100 to 100): {value}", file=sys.stderr)
        return None
    return value


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_serial_data(ser)
            if data is not None:
                processed = process_data(data)
                if processed is not None:
                    print(f"Temperature: {processed:.2f} C")
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("\nProgram terminated.")


if __name__ == "__main__":
    main()

