import signal
import sys
import time

import serial
import serial.tools.list_ports

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 115200
READ_INTERVAL = 5          # seconds between readings
TIMEOUT_S = 1              # per-read timeout
MAX_INIT_RETRIES = 3       # attempts to open the port before giving up


class SerialReader:
    """Exchange data with a connected device over a UART port."""

    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: serial.Serial | None = None
        self._running = True

    # -- lifecycle ----------------------------------------------------------

    def connect(self) -> bool:
        """Open the serial port; return True on success."""
        for attempt in range(1, MAX_INIT_RETRIES + 1):
            try:
                self.serial_port = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                print(f"Connected to {self.port} @ {self.baudrate} baud.")
                return True
            except serial.SerialException as exc:
                print(f"[WARN] Open attempt {attempt}/{MAX_INIT_RETRIES} failed: {exc}")
                if attempt < MAX_INIT_RETRIES:
                    time.sleep(2)
        return False

    def disconnect(self) -> None:
        """Close the serial port if it is open."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    print("Serial port closed.")
            except Exception as exc:                       # pragma: no cover
                print(f"[WARN] Error closing serial port: {exc}")
            finally:
                self.serial_port = None

    # -- main loop ----------------------------------------------------------

    def run(self) -> int:
        """Main read/print loop. Returns process exit code."""
        if not self.connect():
            print("[ERROR] Could not connect to device after retries. Exiting.", file=sys.stderr)
            return 1

        try:
            while self._running:
                try:
                    raw = self.serial_port.readline()
                except serial.SerialException as exc:
                    print(f"[ERROR] Read failed: {exc}", file=sys.stderr)
                    break

                if not raw:
                    # Timed out or empty line — device may be absent or silent.
                    print("[WARN] No data received (timeout).", file=sys.stderr)
                    break

                try:
                    line = raw.decode("utf-8", errors="replace").strip()
                except Exception as exc:
                    print(f"[WARN] Decode error: {exc}", file=sys.stderr)
                    continue

                if not line:
                    continue

                print(f"Received: {line}")

        finally:
            self.disconnect()

        return 0

    # -- signals ------------------------------------------------------------

    def stop(self) -> None:
        self._running = False


def _main() -> int:
    reader = SerialReader(SERIAL_PORT, BAUD_RATE, TIMEOUT_S)

    def _sigint_handler(signum, frame):
        print("\nInterrupt received, stopping...")
        reader.stop()

    signal.signal(signal.SIGINT, _sigint_handler)
    signal.signal(signal.SIGTERM, _sigint_handler)

    return reader.run()


if __name__ == "__main__":
    sys.exit(_main())

