import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

SENSOR_PIN = 17
ECHO_PIN = 22
MAX_DISTANCE_METRES = 1.0
SAMPLE_INTERVAL_S = 50
NUM_CYCLES = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=SENSOR_PIN,
                                max_distance=MAX_DISTANCE_METRES)
    except GPIOZeroError as exc:
        print(f"Failed to initialise HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    cycle = 0
    try:
        while _running and cycle < NUM_CYCLES:
            try:
                distance_m = sensor.distance
                if distance_m is None or distance_m < 0:
                    print("Warning: invalid reading from sensor", file=sys.stderr)
                else:
                    print(f"Distance: {distance_m:.2f} m")
            except DeviceClosed:
                print("Sensor closed unexpectedly", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Sensor read error: {exc}", file=sys.stderr)

            cycle += 1
            if cycle < NUM_CYCLES and _running:
                time.sleep(SAMPLE_INTERVAL_S)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

