import signal
import sys
import serial

PORT = "/dev/serial0"
BAUD = 115200
READ_TIMEOUT_S = 1.0
WRITE_TIMEOUT_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=READ_TIMEOUT_S,
            write_timeout=WRITE_TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                line = ser.readline()
            except serial.SerialTimeoutException:
                continue
            except serial.SerialException as exc:
                print(f"Error: serial communication failed: {exc}", file=sys.stderr)
                return 1

            if not line:
                # Timed out or empty read — keep looping until interrupted.
                continue

            decoded = line.decode("utf-8", errors="replace").strip()
            if decoded:
                print(decoded)
    finally:
        try:
            ser.close()
        except Exception:
