import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
INTERVAL_S = 1.0
NUM_READINGS = 3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT_S,
            write_timeout=READ_TIMEOUT_S,
        )
        print(f"Opened {PORT} @ {BAUD_RATE} baud (timeout={READ_TIMEOUT_S}s).")

        for i in range(NUM_READINGS):
            if not _running:
                print("\nInterrupted by signal; exiting early.", file=sys.stderr)
                break

            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Read error on frame {i + 1}: {exc}", file=sys.stderr)
                break

            if not raw:
                print(f"Frame {i + 1}: no data (timeout).")
            else:
                line = raw.decode("utf-8", errors="replace").strip()
                if line:
                    print(f"Frame {i + 1}: {line}")
                else:
                    print(f"Frame {i + 1}: empty line.")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(INTERVAL_S)

    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("Serial port closed.")
            except Exception as exc:
                print(f"Error closing serial port: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

