import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

SENSOR_PINS = (17, 18, 22, 23)
POLL_INTERVAL = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        for pin in SENSOR_PINS:
            try:
                s = DistanceSensor(echo=pin, trigger=pin ^ 1, max_distance=2.0)
                sensors.append(s)
            except GPIOZeroError as exc:
                print(f"Failed to initialise sensor on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            readings = []
            for idx, s in enumerate(sensors):
                try:
                    d = s.distance
                    if d is None or d < 0 or d > 2.0:
                        readings.append(f"{idx}: N/A")
                    else:
                        readings.append(f"{idx}: {d * 100:.1f} cm")
                except DeviceClosed:
                    readings.append(f"{idx}: closed")
                except GPIOZeroError as exc:
                    readings.append(f"{idx}: error: {exc}")

            print(' '.join(readings))
            time.sleep(POLL_INTERVAL)

    finally:
        for s in sensors:
            try:
                s.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

