import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers for the PWM outputs
PWM_PINS = [4, 17, 22, 27]

# Global list so the signal handler can close devices
_devices = []


def _cleanup():
    """Close every PWMOutputDevice we opened."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass


def _handle_signal(signum, frame):
    print(f"\nReceived signal {signum}, exiting.")
    _cleanup()
    sys.exit(0)


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Open each pin as a PWM output; gpiozero auto-configures frequency=100 Hz.
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin)
            _devices.append(dev)
            print(f"PWM initialized on GPIO{pin} (BCM).")
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on one or more pins: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("PWM states reported every 1 second. Press Ctrl+C to stop.")

    try:
        while True:
            for dev in _devices:
                try:
                    print(f"GPIO{dev.pin}: {dev.value}")
                except DeviceClosed:
                    print(f"GPIO{dev.pin}: device closed unexpectedly", file=sys.stderr)
                except Exception as exc:
                    print(f"GPIO{dev.pin}: read error - {exc}", file=sys.stderr)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

