import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
MAX_INIT_RETRIES = 3
RETRY_DELAY_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate_reading(value):
    """Return True if value is a valid integer in the expected range."""
    try:
        val = int(value)
    except ValueError:
        return False
    return -32768 <= val <= 32767


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        for attempt in range(1, MAX_INIT_RETRIES + 1):
            if not _running:
                print("Aborted by user.", file=sys.stderr)
                return 1
            try:
                ser = serial.Serial(
                    PORT,
                    BAUD_RATE,
                    timeout=READ_TIMEOUT_S,
                    write_timeout=READ_TIMEOUT_S,
                )
                print(f"Connected to {PORT} at {BAUD_RATE} baud.")
                break
            except serial.SerialException as exc:
                print(f"Attempt {attempt}/{MAX_INIT_RETRIES}: failed to open {PORT}: {exc}", file=sys.stderr)
                if attempt < MAX_INIT_RETRIES:
                    time.sleep(RETRY_DELAY_S)
                else:
                    print("Error: could not connect to device after multiple retries.", file=sys.stderr)
                    return 1

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Read error: {exc}", file=sys.stderr)
                return 1

            if not raw:
                # Timed out waiting for data
                continue

            line = raw.decode("ascii", errors="replace").strip()
            if not line:
                continue

            if not _validate_reading(line):
                print(f"Invalid reading: '{line}'", file=sys.stderr)
                continue

            print(f"Reading: {line}")

    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

