import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

TSL2561_ADDR = 0x39
TSL2561_REG_DATA0_LOW = 0x00
TSL2561_REG_DATA1_LOW = 0x04
TSL2561_REG_CHAN0_LOW = 0x14
TSL2561_REG_CHAN1_LOW = 0x16
TSL2561_REG_CONTROL = 0x80
TSL2561_REG_DEVICE_ID = 0x12
TSL2561_DEV_ID = 0x50
TSL2561_POWER_ON = 0x03
TSL2561_AGAIN_1X = 0x00
TSL2561_AWU_101MS = 0x01

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _read_u16le(bus, addr, reg):
    msg_w = i2c_msg.write(addr, [reg])
    msg_r = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(msg_w, msg_r)
    return (msg_r.buf[0] << 8) | msg_r.buf[1]


def _write_reg(bus, addr, reg, val):
    msg = i2c_msg.write(addr, [reg, val])
    bus.i2c_rdwr(msg)


def init_tsl2561(bus, addr):
    try:
        dev_id = _read_reg(bus, addr, TSL2561_REG_DEVICE_ID)
    except OSError:
        raise RuntimeError("No device acknowledged at 0x%02X" % addr)
    if dev_id != TSL2561_DEV_ID:
        raise RuntimeError(
            "Unexpected device ID 0x%02X (expected 0x%02X)" % (dev_id, TSL2561_DEV_ID)
        )
    _write_reg(bus, addr, TSL2561_REG_CONTROL, TSL2561_POWER_ON)
    _write_reg(bus, addr, TSL2561_REG_CONTROL, TSL2561_AGAIN_1X | TSL2561_AWU_101MS)
    time.sleep(0.01)


def read_lux(bus, addr):
    ch0 = _read_u16le(bus, addr, TSL2561_REG_CHAN0_LOW)
    ch1 = _read_u16le(bus, addr, TSL2561_REG_CHAN1_LOW)
    if ch0 == 0 or ch1 == 0:
        raise ValueError("Channnel zero or one saturated")
    ratio = ch0 / ch1
    if ratio < 0.5:
        lux = 0.0
    elif ratio < 0.61:
        lux = 0.0304 * ch0 - 0.062 * ch0 * (ratio ** 1.0)
    elif ratio < 0.67:
        lux = 0.0224 * ch0 - 0.031 * ch1
    elif ratio < 0.80:
        lux = 0.0128 * ch0 - 0.0153 * ch1
    elif ratio < 1.3:
        lux = 0.00146 * ch0 - 0.00112 * ch1
    else:
        lux = 0.0
    return max(0.0, min(lux, 25000.0))


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(1)
    except OSError as e:
        print("Failed to open I2C bus 1: %s" % e, file=sys.stderr)
        sys.exit(1)

    try:
        init_tsl2561(bus, TSL2561_ADDR)
    except RuntimeError as e:
        print("TSL2561 init failed: %s" % e, file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                lux = read_lux(bus, TSL2561_ADDR)
            except (OSError, ValueError) as e:
                print("Read error: %s" % e, file=sys.stderr)
                break
            print("%.2f" % lux)
            time.sleep(0.1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

