import signal
import sys
import time

import paho.mqtt.client as mqtt

# Configuration
MQTT_BROKER = "your_mqtt_broker"
MQTT_PORT = 1883
MQTT_TOPIC = "sensor_data"
PUBLISH_INTERVAL = 5  # seconds


class SensorPublisher:
    """Publishes sensor data to an MQTT broker."""

    def __init__(self, broker: str, port: int, topic: str):
        self.broker = broker
        self.port = port
        self.topic = topic
        self._running = True
        self.client: mqtt.Client | None = None

    def connect(self) -> None:
        """Connects to the MQTT broker."""
        try:
            self.client = mqtt.Client()
            self.client.connect(self.broker, self.port)
            self.client.loop_start()
        except Exception as e:
            print(f"Error connecting to MQTT broker: {e}", file=sys.stderr)
            raise

    def publish_reading(self, reading: str) -> None:
        """Publishes a sensor reading to the configured MQTT topic."""
        if not self.client or not self.client.is_connected():
            print("MQTT client not connected; skipping publish.", file=sys.stderr)
            return
        try:
            result = self.client.publish(self.topic, payload=reading, qos=0)
            if result.rc != mqtt.MQTT_ERR_SUCCESS:
                print(f"Failed to publish message: {result.rc}", file=sys.stderr)
        except Exception as e:
            print(f"Error publishing message: {e}", file=sys.stderr)

    def stop(self) -> None:
        """Stops the publisher and releases resources."""
        self._running = False
        if self.client:
            try:
                self.client.loop_stop()
                self.client.disconnect()
            except Exception:
                pass
            self.client = None

    def run(self) -> None:
        """Runs the publisher loop until interrupted."""
        while self._running:
            try:
                sensor_reading = "temperature_25.4"
                self.publish_reading(sensor_reading)
                time.sleep(PUBLISH_INTERVAL)
            except KeyboardInterrupt:
                break
            except Exception as e:
                print(f"Unexpected error in publisher loop: {e}", file=sys.stderr)
                time.sleep(1)


def main() -> None:
    publisher = SensorPublisher(MQTT_BROKER, MQTT_PORT, MQTT_TOPIC)

