import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
MAX_INIT_RETRIES = 3
RETRY_DELAY_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port() -> serial.Serial | None:
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            ser = serial.Serial(
                port=PORT,
                baudrate=BAUD_RATE,
                timeout=READ_TIMEOUT_S,
                write_timeout=READ_TIMEOUT_S,
            )
            if not ser.is_open:
                ser.open()
            return ser
        except serial.SerialException as exc:
            print(f"Attempt {attempt}/{MAX_INIT_RETRIES} failed to open {PORT}: {exc}", file=sys.stderr)
            if attempt < MAX_INIT_RETRIES:
                time.sleep(RETRY_DELAY_S)
    return None


def read_data(serial_port: serial.Serial) -> str | None:
    try:
        raw = serial_port.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode("utf-8", errors="replace").strip()


def main() -> int:
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_port = open_serial_port()
    if serial_port is None:
        print("Failed to open serial port after retries.", file=sys.stderr)
        return 1

    try:
        while _running:
            data = read_data(serial_port)
            if data:
                print(data)
            else:
                break
    finally:
        try:
            serial_port.close()
        except Exception:
            pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

