import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

TCS34725_ADDRESS = 0x29
TCS34725_COMMAND_BIT = 0x80
TCS34725_REG_ENABLE = 0x00
TCS34725_REG_CONTROL = 0x01
TCS34725_REG_STATUS = 0x03
TCS34725_REG_CDATAL = 0x14

ENABLE_PON = 0x01
ENABLE_AEN = 0x02
STATUS_AVALID = 0x01

READ_INTERVAL_S = 0.01
MAX_CONSECUTIVE_ERRORS = 10


class TCS34725:
    def __init__(self, bus_number=1, address=TCS34725_ADDRESS):
        self.address = address
        self._bus = None
        try:
            self._bus = SMBus(bus_number)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {bus_number}: {exc}") from exc

    def _write_reg(self, reg, value):
        data = bytes([reg | TCS34725_COMMAND_BIT, value])
        self._bus.write_i2c_block_data(self.address, reg | TCS4725_COMMAND_BIT, [value])

    def _read_reg(self, reg):
        data = bytes([reg | TCS34725_COMMAND_BIT])
        result = self._bus.read_i2c_block_data(self.address, reg | TCS34725_COMMAND_BIT, 1)
        return result[0]

    def _read_block(self, reg, length):
        data = bytes([reg | TCS34725_COMMAND_BIT]) + bytes([0] * length)
        result = self._bus.read_i2c_block_data(self.address, reg | TCS34725_COMMAND_BIT, length)
        return result

    def initialize(self):
        self._write_reg(TCS34725_REG_ENABLE, ENABLE_PON | ENABLE_AEN)
        time.sleep(0.01)

    def read_raw_data(self):
        status = self._read_reg(TCS34725_REG_STATUS)
        if not (status & STATUS_AVALID):
            return None, None, None, None
        raw = self._read_block(TCS34725_REG_CDATAL, 4)
        return (
            int.from_bytes(raw[0:2], "little"),
            int.from_bytes(raw[2:4], "little"),
        )

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._bus = None


def main():
    sensor = None
    running = True

    def _signal_handler(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        sensor = TCS34725(bus_number=1, address=TCS34725_ADDRESS)
        sensor.initialize()
    except RuntimeError as exc:
        print(f"Initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

    consecutive_errors = 0
    try:
        while running:
            try:
                red, green, blue, clear = sensor.read_raw_data()
                if red is None:
                    consecutive_errors += 1
                    if consecutive_errors >= MAX_CONSECUTIVE_ERRORS:
                        print("Sensor read error: no valid data", file=sys.stderr)
                        break
                    time.sleep(READ_INTERVAL_S)
                    continue
                consecutive_errors = 0
                print(
                    f"R:{red:6d} G:{green:6d} B:{blue:6d} C:{clear:6d}"
                )
                time.sleep(READ_INTERVAL_S)
            except OSError as exc:
                consecutive_errors += 1
                if consecutive_errors >= MAX_CONSECUTIVE_ERRORS:
                    print(f"I2C communication error: {exc}", file=sys.stderr)
                    break
                time.sleep(READ_INTERVAL_S)
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

