import adafruit_dht

# Global list of devices so cleanup can reach them.
_devices = []

def cleanup(signum=None, frame=None):
    """Release every sensor we opened."""
    for dev in _devices:
        try:
            dev.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Map BCM pin numbers to board pins.
    pin_map = {
        4: board.D4,
        17: board.D17,
        18: board.D18,
        22: board.D22,
        23: board.D23,
        27: board.D27,
    }

    # Open each device; store references so cleanup can reach them.
    for bcm_pin in sorted(pin_map.keys()):
        try:
            dev = adafruit_dht.DHT22(pin_map[bcm_pin], use_pulseio=False)
            _devices.append(dev)
            print(f"Opened DHT22 on BCM {bcm_pin}")
        except Exception as exc:
            print(f"Failed to open BCM {bcm_pin}: {exc}", file=sys.stderr)
            continue

    if not _devices:
        print("No sensors could be opened. Exiting.", file=sys.stderr)
        sys.exit(1)

    # Run three readings, one every 5 seconds.
    for cycle in range(1, 4):
        for dev in _devices:
            try:
                temp = dev.temperature
                hum = dev.humidity
                if temp is not None and hum is not None:
                    print(f"Cycle {cycle}: Temp={temp:.1f}C Hum={hum:.1f}%")
                else:
                    print(f"Cycle {cycle}: Read failed on BCM {dev.pin.number}")
            except Exception as exc:
                print(f"Cycle {cycle}: Read error on BCM {dev.pin.number}: {exc}", file=sys.stderr)
        time.sleep(5)

    cleanup()

if __name__ == "__main__":
