import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_INTERVAL = 0.5
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baudrate, retries=MAX_INIT_RETRIES, delay=INIT_RETRY_DELAY):
    last_err = None
    for attempt in range(1, retries + 1):
        try:
            ser = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=1.0,
                write_timeout=1.0,
            )
            if not ser.is_open:
                ser.open()
            return ser
        except serial.SerialException as e:
            last_err = e
            print(f"Serial init attempt {attempt}/{retries} failed: {e}", file=sys.stderr)
            if attempt < retries:
                time.sleep(delay)
    raise RuntimeError(f"Failed to open {port} after {retries} attempts: {last_err}")


def read_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Read error: {e}", file=sys.stderr)
        return None


def process_data(data):
    if not data:
        return False
    print(f"Received: {data}")
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    except RuntimeError as e:
        print(f"Fatal: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            if ser.is_open:
                ser.close()
        except Exception:
            pass
        print("\nExiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

TCS34725_ADDR = 0x29
REG_COMMAND = 0x00
REG_STATUS = 0x10
REG_DATA0 = 0x14

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _read_block(bus, addr, reg, n):
    write = i2c_msg.write(addr, bytes([reg]))
    read = i2c_msg.read(addr, n)
    bus.i2c_rdwr(write, read)
    return list(read)


def _write_reg(bus, addr, reg, data):
    msg = i2c_msg.write(addr, bytes([reg]) + data)
    bus.i2c_rdwr(msg)


def _read_reg(bus, addr, reg):
    write = i2c_msg.write(addr, bytes([reg]))
    read = i2c_msg.read(addr, 1)
    bus.i2c_rdwr(write, read)
    return list(read)[0]


def init_sensor(bus, addr):
    try:
        _write_reg(bus, addr, REG_COMMAND, [0x00])
        status = _read_reg(bus, addr, REG_STATUS)
        if status & 0x80:
            raise RuntimeError("Device not ready (status bit 7 set)")
        return True
    except Exception as e:
        print(f"Error initializing TCS34725: {e}", file=sys.stderr)
        return False


def read_color_data(bus, addr):
    data = _read_block(bus, addr, REG_DATA0, 4)
    if len(data) != 4:
        raise IOError("Incomplete data block")
    raw = (data[0] << 16) | (data[1] << 8) | data[2]
    return raw


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(1)
    except Exception as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        if not init_sensor(bus, TCS34725_ADDR):
            sys.exit(1)

        while running:
            try:
                raw = read_color_data(bus, TCS34725_ADDR)
                print(raw)
            except (IOError, OSError) as e:
                print(f"Read error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)

            if running:
                time.sleep(1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

SENSOR_PIN = 25
POLL_INTERVAL = 0.5
MAX_RETRIES = 3
RETRY_DELAY = 0.1


def main() -> int:
    sensor = None
    try:
        sensor = DistanceSensor(echo=SENSOR_PIN, trigger=SENSOR_PIN, max_distance=2.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on GPIO {SENSOR_PIN}: {exc}", file=sys.stderr)
        return 1

    running = True

    def _shutdown(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        while running:
            ok = False
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    distance_m = sensor.distance
                    if distance_m is None or distance_m < 0:
                        raise RuntimeError("sensor returned invalid reading")
                    print(f"Distance: {distance_m * 100:.2f} cm")
                    ok = True
                    break
                except (DeviceClosed, RuntimeError, GPIOZeroError) as exc:
                    if attempt < MAX_RETRIES:
                        time.sleep(RETRY_DELAY)
                    else:
                        print(f"HC-SR04 read failed after {MAX_RETRIES} attempts: {exc}", file=sys.stderr)
            if not ok:
                print("HC-SR04 read skipped due to error.", file=sys.stderr)
            if running:
                time.sleep(POLL_INTERVAL)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

import board
import adafruit_dht

# Global list of sensors so cleanup can reach them.
_SENSORS = []

def _cleanup(signum=None, frame=None):
    """Release every sensor we opened before exiting."""
    for s in list(_SENSORS):
        try:
            s.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for clean shutdown on SIGINT / SIGTERM.
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Map BCM pin numbers to board.Dxx constants.
    PIN_MAP = {
        4: board.D4,
        17: board.D17,
        27: board.D27,
    }

    sensors = []
    for bcm_pin in (4, 17, 27):
        pin = PIN_MAP.get(bcm_pin)
        if pin is None:
            print(f"Warning: no board.D{bcm_pin} constant; skipping.", file=sys.stderr)
            continue
        try:
            s = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(s)
            _SENSORS.append(s)
        except Exception as exc:
            print(f"Failed to initialise DHT22 on GPIO {bcm_pin}: {exc}", file=sys.stderr)
            continue

    if not sensors:
        print("No DHT22 sensors could be initialised. Exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("DHT22 monitoring started. Press Ctrl+C to stop.")

    while True:
        for s in sensors:
            try:
                temp = s.temperature
                hum = s.humidity
                if temp is not None and hum is not None:
                    print(f"Temp: {temp:.1f} C  Humidity: {hum:.1f} %")
            except RuntimeError as exc:
                # DHT22 reads occasionally fail; log and keep going.
                print(f"Read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error reading sensor: {exc}", file=sys.stderr)
        time.sleep(1)

if __name__ == "__main__":
    main()

