import signal
import sys
import time

import board
import busio
from adafruit_ads1x15.ads1015 import ADS1015
from adafruit_ads1x15.analog_in import AnalogIn

# ADS1015 default I2C address is 0x48; some breakout boards use 0x19.
ADS_ADDRESS = 0x19
SAMPLE_INTERVAL_S = 1.0


class SensorReader:
    def __init__(self, address: int):
        self._running = True
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
        except Exception as exc:
            print(f"Failed to initialize I2C bus: {exc}", file=sys.stderr)
            raise

        try:
            self.ads = ADS1015(self.i2c, address=address)
        except ValueError as exc:
            print(
                f"No ADS1015 found at 0x{address:02X} on the I2C bus: {exc}",
                file=sys.stderr,
            )
            raise
        except OSError as exc:
            print(
                f"I2C communication error with ADS1015 at 0x{address:02X}: {exc}",
                file=sys.stderr,
            )
            raise

        self.channel = AnalogIn(self.ads, 0)

    def read_channel(self) -> float | None:
        """Return a signed 16-bit value in the range -32768..+32767, or None on error."""
        try:
            return self.channel.value
        except OSError as exc:
            print(f"I2C read error: {exc}", file=sys.stderr)
            return None

    def stop(self) -> None:
        self._running = False

    def _handle_signal(self, signum, frame):
        self.stop()

    def run(self) -> int:
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        while self._running:
            reading = self.read_channel()
            if reading is not None:
                print(reading)
            else:
                print("Skipping sample due to read error.", file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL_S)

        return 0


def main() -> int:
    try:
        reader = SensorReader(ADS_ADDRESS)
    except Exception:
        return 1

    try:
        return reader.run()
    finally:
        # Release the underlying I2C bus so the GPIO pins are freed.
        try:
            reader.i2c.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    sys.exit(main())

