import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_INTERVAL = 0.05
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baudrate, retries=MAX_INIT_RETRIES, delay=INIT_RETRY_DELAY):
    last_err = None
    for attempt in range(1, retries + 1):
        try:
            ser = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=1.0,
                write_timeout=1.0,
            )
            if not ser.is_open:
                ser.open()
            return ser
        except serial.SerialException as e:
            last_err = e
            print(f"Serial init attempt {attempt}/{retries} failed: {e}", file=sys.stderr)
            if attempt < retries:
                time.sleep(delay)
    raise RuntimeError(f"Failed to open {port} after {retries} attempts: {last_err}")


def read_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Read error: {e}", file=sys.stderr)
        return None


def process_data(data):
    if not data:
        return False
    print(f"Received: {data}")
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    except RuntimeError as e:
        print(f"Fatal: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            if ser.is_open:
                ser.close()
        except Exception:
            pass
        print("\nExiting.")


if __name__ == "__main__":
    main()

