import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True
bus = None


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

try:
    bus = SMBus(1)
except OSError as e:
    print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
    sys.exit(1)

try:
    # Wake up MPU6050 (clear sleep bit)
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
    except OSError as e:
        print(f"Error: MPU6050 not detected at address 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
        sys.exit(1)

    for i in range(5):
        if not running:
            break

        try:
            data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        except OSError as e:
            print(f"Error: failed to read accelerometer data: {e}", file=sys.stderr)
            sys.exit(1)

        ax = (data[0] << 8) | data[1]
        ay = (data[2] << 8) | data[3]
        az = (data[4] << 8) | data[5]

        # Convert to signed 16-bit values
        if ax >= 0x8000:
            ax -= 0x10000
        if ay >= 0x8000:
            ay -= 0x10000
        if az >= 0x8000:
            az -= 0x10000

        print(f"Reading {i + 1}/5: X={ax}, Y={ay}, Z={az}")
        time.sleep(0.1)

finally:
    if bus is not None:
        bus.close()

