import signal
import sys
import time

import spidev
from mfrc522 import MFRC522

READ_INTERVAL = 0.001
MAX_RETRIES = 3


class RFIDReader:
    def __init__(self):
        self._spi = None
        self._reader = None
        self._running = True

    # ---- lifecycle ---------------------------------------------------------
    def open(self):
        try:
            self._spi = spidev.SpiDev()
            self._spi.open(0, 0)
            self._spi.max_speed_hz = 1_000_000
            self._spi.mode = 0
        except Exception as exc:
            print(f"Failed to initialise SPI: {exc}", file=sys.stderr)
            raise

        try:
            self._reader = MFRC522()
        except Exception as exc:
            print(f"Failed to initialise MFRC522: {exc}", file=sys.stderr)
            self.close()
            raise

    def close(self):
        if self._spi is not None:
            try:
                self._spi.close()
            except Exception:
                pass
            self._spi = None
        if self._reader is not None:
            try:
                self._reader.PICC_HaltA()
            except Exception:
                pass
            self._reader = None

    # ---- main loop ---------------------------------------------------------
    def run(self):
        self.open()
        try:
            while self._running:
                ok = False
                for attempt in range(1, MAX_RETRIES + 1):
                    if not self._running:
                        break
                    try:
                        status, uid = self._reader.MFRC522_Request(self._reader.PICC_REQIDL)
                        if status == self._reader.MI_OK:
                            ok = True
                            break
                    except Exception as exc:
                        print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {exc}",
                              file=sys.stderr)
                    if attempt < MAX_RETRIES:
                        time.sleep(0.001)
                if ok:
                    print(uid)
                else:
                    print("No card detected.", file=sys.stderr)
                time.sleep(READ_INTERVAL)
        finally:
            self.close()

    # ---- signals -----------------------------------------------------------
    def stop(self, *_args):
        self._running = False


def main():
    reader = RFIDReader()
    signal.signal(signal.SIGINT, reader.stop)
    signal.signal(signal.SIGTERM, reader.stop)
    reader.run()


if __name__ == "__main__":
    main()

