import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin numbers
PINS = [12, 16]

# Global list so the signal handler can close devices
_devices = []


def cleanup(signum=None, frame=None):
    """Close every device we opened; ignore errors during teardown."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        # Create digital output devices (active_high=True is the default)
        _devices = [DigitalOutputDevice(pin) for pin in PINS]
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            for dev in _devices:
                print(f"GPIO {dev.pin}: {'HIGH' if dev.value else 'LOW'}")
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

