#!/usr/bin/env python3
"""Control a digital output on GPIO 18 (BCM) with validation.

Wiring: digital output module IN pin -> GPIO 18 (physical pin 12).
"""

import signal
import sys
from gpiozero import DigitalOutputDevice

PIN = 18
VALID_VALUES = {"on", "off", "toggle"}


def validate(value: str) -> bool:
    """Return True if *value* is one of the allowed states."""
    return value.lower() in VALID_VALUES


def apply_state(device: DigitalOutputDevice, state: str) -> None:
    """Apply the requested state to the output device."""
    if state == "on":
        device.on()
    elif state == "off":
        device.off()
    else:  # toggle
        device.toggle()


def main() -> int:
    try:
        device = DigitalOutputDevice(PIN)
    except Exception as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    # Ensure cleanup on SIGINT / SIGTERM.
    def shutdown(signum, frame):
        print("\nShutting down...")
        try:
            device.close()
        except Exception:
            pass
        sys.exit(0)

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    try:
        for cycle in range(3):
            try:
                raw = input("Enter state (on/off/toggle): ").strip()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if not raw:
                continue

            state = raw.lower()
            if not validate(state):
                print(f"Invalid state '{state}'. Valid: {', '.join(sorted(VALID_VALUES))}")
                continue

            try:
                apply_state(device, state)
                print(f"Cycle {cycle + 1}/3: GPIO {PIN} set to {state}")
            except Exception as exc:
                print(f"GPIO write error on cycle {cycle + 1}: {exc}", file=sys.stderr)
    finally:
        try:
            device.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Sample one channel from an MCP3008 via adafruit-circuitpython-mcp3xxx.

Wiring:
  MCP3008 VDD -> 3V3 (Pin 1)
  MCP3008 VREF -> 3V3 (Pin 1)
  MCP3008 AGND -> GND (Pin 6)
  MCP3008 DGND -> GND (Pin 9)
  MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
  MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
  MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
  MCP3008 CS   -> GPIO8  (CE0,  Pin 24)

The channel argument is a zero-based index into the 8 channels of the
MCP3008.  Valid ranges are 0-7.
"""

import signal
import sys

import board
import busio
from digitalio import DigitalInOut
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn


MIN_CHANNEL = 0
MAX_CHANNEL = 7


def _validate_channel(channel: int) -> None:
    if not isinstance(channel, int):
        raise TypeError("channel must be an integer")
    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        raise ValueError(
            f"channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}, "
            f"got {channel}"
        )


def read_mcp3008_channel(i2c_bus, adc, channel: int) -> int | None:
    """Return a valid raw 10-bit value or None on failure."""
    try:
        _validate_channel(channel)
    except (TypeError, ValueError) as exc:
        print(f"Error validating channel: {exc}", file=sys.stderr)
        return None

    try:
        chan = AnalogIn(adc, channel)
    except Exception as exc:
        print(f"Error initializing AnalogIn on channel {channel}: {exc}",
              file=sys.stderr)
        return None

    try:
        return int(chan.value)
    except Exception as exc:
        print(f"Error reading channel {channel}: {exc}", file=sys.stderr)
        return None


def main() -> int:
    i2c = None
    adc = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        adc = MCP3008(i2c)
        reading = read_mcp3008_channel(i2c, adc, 0)
        if reading is not None:
            print(reading)
            return 0
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        return 130
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        if adc is not None:
            try:
                adc.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_INTERVAL = 0.1
MAX_INIT_RETRIES = 5
INIT_RETRY_DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baudrate, retries=MAX_INIT_RETRIES, delay=INIT_RETRY_DELAY):
    last_err = None
    for attempt in range(1, retries + 1):
        try:
            ser = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=1.0,
                write_timeout=1.0,
            )
            if not ser.is_open:
                ser.open()
            return ser
        except serial.SerialException as e:
            last_err = e
            print(f"Serial init attempt {attempt}/{retries} failed: {e}", file=sys.stderr)
            if attempt < retries:
                time.sleep(delay)
    raise RuntimeError(f"Failed to open {port} after {retries} attempts: {last_err}")


def read_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Read error: {e}", file=sys.stderr)
        return None


def process_data(data):
    if not data:
        return False
    print(f"Received: {data}")
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    except RuntimeError as e:
        print(f"Fatal: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            if ser.is_open:
                ser.close()
        except Exception:
            pass
        print("\nExiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 17
DUTY_CYCLE_MIN = 0.0
DUTY_CYCLE_MAX = 100.0
INTERVAL_SECONDS = 1.0


def validate_duty_cycle(duty_cycle: float) -> bool:
    """Reject values outside the documented range."""
    return DUTY_CYCLE_MIN <= duty_cycle <= DUTY_CYCLE_MAX


def main() -> int:
    pwm = None
    try:
        pwm = PWMOutputDevice(PWM_PIN)
        print(f"PWM initialized on GPIO {PWM_PIN} (BCM).")

        while True:
            try:
                duty_cycle = float(input("Enter duty cycle (0-100): "))
            except ValueError:
                print("Invalid input. Please enter a number.")
                continue

            if not validate_duty_cycle(duty_cycle):
                print(
                    f"Duty cycle out of range [{DUTY_CYCLE_MIN}, {DUTY_CYCLE_MAX}] "
                    f"({duty_cycle})."
                )
                continue

            try:
                pwm.value = duty_cycle / 100.0
                print(f"Duty cycle set to {duty_cycle:.1f}%")
            except DeviceClosed:
                print("Error: PWM device is closed.")
                return 1
            except GPIOZeroError as exc:
                print(f"GPIO error setting duty cycle: {exc}")
                return 1

            time.sleep(INTERVAL_SECONDS)

    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}")
        return 1
    finally:
        if pwm is not None:
            try:
                pwm.close()
            except Exception:
                pass
        print("PWM stopped.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 14
POLL_INTERVAL = 5.0


class PwmController:
    def __init__(self, pin: int):
        self.pin = pin
        self.device: PWMOutputDevice | None = None
        self._running = True

    def setup(self) -> None:
        try:
            self.device = PWMOutputDevice(pin=self.pin)
        except GPIOZeroError as exc:
            print(f"Error setting up PWM on GPIO {self.pin}: {exc}", file=sys.stderr)
            raise

    def apply_pwm(self, duty_cycle: float) -> bool:
        if self.device is None or self.device.closed:
            print("PWM device is not initialized.", file=sys.stderr)
            return False
        try:
            self.device.value = duty_cycle / 100.0
            print(f"PWM duty cycle set to: {duty_cycle:.2f}%")
            return True
        except DeviceClosed:
            print("PWM device has been closed unexpectedly.", file=sys.stderr)
            return False
        except GPIOZeroError as exc:
            print(f"Error applying PWM value: {exc}", file=sys.stderr)
            return False

    def cleanup(self) -> None:
        if self.device is not None and not self.device.closed:
            try:
                self.device.close()
            except DeviceClosed:
                pass
            except GPIOZeroError as exc:
                print(f"Error closing PWM device: {exc}", file=sys.stderr)
        self.device = None

    def stop(self, *_args) -> None:
        self._running = False


def main() -> int:
    controller = PwmController(PWM_PIN)

    signal.signal(signal.SIGINT, controller.stop)
    signal.signal(signal.SIGTERM, controller.stop)

    try:
        controller.setup()
    except GPIOZeroError:
        return 1

    try:
        while controller._running:
            if not controller.apply_pwm(50.0):
                break
            time.sleep(POLL_INTERVAL)
    finally:
        controller.cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

