        with SMBus(I2C_BUS) as bus:
            while _running:
                try:
                    value = read_pca9685_register(bus, 0x00)
                except OSError as exc:
                    print(f"Error reading register 0x00: {exc}", file=sys.stderr)
                    break

                print(value)
                time.sleep(READ_INTERVAL_S)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

