import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_INTERVAL = 0.1
MAX_INIT_RETRIES = 5
INIT_RETRY_DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port() -> serial.Serial | None:
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            ser = serial.Serial(
                port=PORT,
                baudrate=BAUD_RATE,
                timeout=READ_INTERVAL,
                write_timeout=READ_INTERVAL,
            )
            if not ser.is_open:
                ser.open()
            return ser
        except serial.SerialException as e:
            print(f"Attempt {attempt}/{MAX_INIT_RETRIES} failed to open {PORT}: {e}", file=sys.stderr)
            if attempt < MAX_INIT_RETRIES:
                time.sleep(INIT_RETRY_DELAY)
    return None


def read_data(serial_port: serial.Serial) -> str | None:
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode("utf-8", errors="replace").strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None


def main() -> int:
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_port = open_serial_port()
    if serial_port is None:
        print("Failed to open serial port after retries. Exiting.", file=sys.stderr)
        return 1

    try:
        while _running:
            data = read_data(serial_port)
            if data is not None:
                print(data)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            if serial_port.is_open:
                serial_port.close()
        except Exception:
            pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
INTERVAL_S = 2.0
NUM_READINGS = 3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT_S,
            write_timeout=READ_TIMEOUT_S,
        )
        print(f"Opened {PORT} @ {BAUD_RATE} baud.")

        for i in range(NUM_READINGS):
            if not _running:
                print("\nInterrupted by signal.", file=sys.stderr)
                break

            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Read error on byte {i}: {exc}", file=sys.stderr)
                break

            if raw:
                line = raw.decode("utf-8", errors="replace").strip()
                if line:
                    print(f"Reading {i + 1}/{NUM_READINGS}: {line}")
                else:
                    print(f"Reading {i + 1}/{NUM_READINGS}: <empty>")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS}: <timeout>")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(INTERVAL_S)

    except serial.SerialException as exc:
        print(f"Device not found or cannot open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

SENSOR_PINS = (17, 22, 27)
POLL_INTERVAL = 0.5
MAX_DISTANCE_METRES = 1.0
MIN_DISTANCE_METRES = 0.0


def report(sensor: DistanceSensor) -> None:
    """Print distance readings from each configured sensor."""
    try:
        distances = sensor.distances
    except DeviceClosed:
        print("Sensor closed; skipping this cycle.", file=sys.stderr)
        return
    except GPIOZeroError as exc:
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return

    if distances is None or len(distances) < len(SENSOR_PINS):
        print("Incomplete reading; retrying...", file=sys.stderr)
        return

    parts = []
    for idx, dist in enumerate(distances):
        clamped = max(MIN_DISTANCE_METRES, min(dist, MAX_DISTANCE_METRES))
        parts.append(f"S{idx + 1}={clamped:.2f}m")
    print(", ".join(parts))


def main() -> int:
    sensors = []
    try:
        for pin in SENSOR_PINS:
            s = DistanceSensor(echo=pin, trigger=pin ^ 1, max_distance=MAX_DISTANCE_METRES)
            sensors.append(s)

        while True:
            for s in sensors:
                report(s)
            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        pass
    finally:
        for s in sensors:
            try:
                s.close()
            except Exception:
                pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Control a relay on GPIO 17 and GPIO 18 via gpiozero.

Wiring:
  - Relay 1: GPIO 17 -> relay module IN/OUT (active-HIGH)
  - Relay 2: GPIO 18 -> relay module IN/OUT (active-HIGH)

The program reads two integers from stdin and applies them as booleans
to the corresponding GPIO pins.  It reports the applied state and exits.
"""

import sys
from signal import signal, SIGINT, SIGTERM

try:
    from gpiozero import OutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)


RELAY_PINS = (17, 18)
_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def apply_relay_state(relay: OutputDevice, pin: int, state: bool) -> None:
    """Apply *state* (True=ON, False=OFF) to *relay* and report it."""
    try:
        relay.value = 1 if state else 0
        print(f"GPIO {pin} set to {'ON' if state else 'OFF'}")
    except Exception as exc:
        print(f"Error setting GPIO {pin}: {exc}", file=sys.stderr)


def main() -> int:
    # Register signal handlers for clean shutdown
    signal(SIGINT, _handle_signal)
    signal(SIGTERM, _handle_signal)

    relays = {}
    try:
        for pin in RELAY_PINS:
            relays[pin] = OutputDevice(pin)

        # Read two integers from stdin
        try:
            a = int(input("Enter value for GPIO 17 (0 or 1): ").strip())
            b = int(input("Enter value for GPIO 18 (0 or 1): ").strip())
        except ValueError:
            print("Invalid input. Please enter integers 0 or 1.", file=sys.stderr)
            return 1
        except EOFError:
            print("No input received.", file=sys.stderr)
            return 1

        if a not in (0, 1) or b not in (0, 1):
            print("Invalid input. Values must be 0 or 1.", file=sys.stderr)
            return 1

        apply_relay_state(relays[17], 17, bool(a))
        apply_relay_state(relays[18], 18, bool(b))

    except Exception as exc:
        print(f"An error occurred: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in list(relays.values()):
            try:
                dev.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())
